  </style>
</head>
<body>
  <main>
    <h1>Workboard</h1>
    <form id="create-form">
      <label>Project name<input id="project-name" name="name" type="text" autocomplete="off"></label>
      <button type="submit">Create project</button>
    </form>
    <label>Project filter<select id="project-filter"><option value="false">Active</option><option value="true">Archived</option></select></label>
    <p id="alert" role="alert" aria-live="polite"></p>
    <ul id="projects" aria-label="Projects"></ul>
  </main>
  <script type="module">
    const list = document.querySelector('#projects');
    const alertBox = document.querySelector('#alert');
    async function loadProjects() {
      const archived = document.querySelector('#project-filter').value;
      const response = await fetch(`/api/projects?archived=${archived}`);
      const projects = await response.json();
      list.replaceChildren(...projects.map(project => {
        const row = document.createElement('li');
        row.className = 'project-row';
        row.dataset.testid = 'project-row';
        const name = document.createElement('span');
        name.textContent = project.name;
        const actions = document.createElement('div');
        const summary = document.createElement('span');
        summary.dataset.testid = 'project-summary';
        summary.textContent = `${project.completed_count}/${project.total_count} completed`;
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = 'Open project';
        button.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
        const archive = document.createElement('button');
        archive.type = 'button';
        archive.textContent = project.archived ? 'Restore project' : 'Archive project';
        archive.addEventListener('click', async () => {
          await fetch(`/api/projects/${project.id}/${project.archived ? 'restore' : 'archive'}`, { method: 'POST' });
          await loadProjects();
        });
        actions.append(button, archive);
        row.append(name, summary, actions);
        return row;
      }));
    }
    document.querySelector('#create-form').addEventListener('submit', async event => {
      event.preventDefault();
      alertBox.textContent = '';
      const name = document.querySelector('#project-name').value.trim();
      if (!name) { alertBox.textContent = 'Project name is required'; return; }
      const response = await fetch('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) });
      if (!response.ok) { const error = await response.json(); alertBox.textContent = error.error || 'Unable to create project'; return; }
      document.querySelector('#project-name').value = '';
      await loadProjects();
    });
    document.querySelector('#project-filter').addEventListener('change', loadProjects);
    loadProjects();
  </script>
</body>
</html>
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Project · Workboard</title>
  <style>
    body { max-width: 48rem; margin: 3rem auto; padding: 0 1rem; font: 16px/1.5 system-ui, sans-serif; color: #172033; }
    button { font: inherit; padding: .55rem .75rem; cursor: pointer; }
    form { display: flex; gap: .6rem; align-items: end; flex-wrap: wrap; margin-top: 1rem; }
    label { display: grid; gap: .25rem; }
    input, select { font: inherit; padding: .55rem .75rem; }
    #alert { color: #a12622; min-height: 1.5em; }
    #tasks { list-style: none; padding: 0; }
    .task-row { border-top: 1px solid #d8deea; padding: .85rem 0; display: flex; align-items: center; gap: .65rem; }
    .task-row input[type="text"] { min-width: 8rem; }
    .task-row select { font: inherit; padding: .55rem .75rem; }
  </style>
</head>
<body>
  <main>
    <button id="back" type="button">Projects</button>
    <h1 id="project-name"></h1>
    <p id="archived-banner" hidden>Archived project</p>
    <p id="missing" role="alert" hidden>Project not found</p>
    <form id="rename-form" hidden>
      <label>New project name<input id="new-project-name" name="name" type="text" autocomplete="off"></label>
      <button type="submit">Rename project</button>
    </form>
    <section id="task-section" hidden aria-label="Tasks">
      <form id="create-form">
        <label>Task title<input id="task-title" name="title" type="text" autocomplete="off"></label>
        <button type="submit">Create task</button>
      </form>
      <p id="alert" role="alert" aria-live="polite"></p>
      <label>Task filter<select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></label>
      <ul id="tasks" aria-label="Tasks"></ul>
    </section>
  </main>
  <script type="module">
    document.querySelector('#back').addEventListener('click', () => { window.location.href = '/'; });
    const id = window.location.pathname.split('/').pop();
    const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
    if (response.ok) {
      const project = await response.json();
      document.querySelector('#project-name').textContent = project.name;
      const renameForm = document.querySelector('#rename-form');
      renameForm.hidden = false;
      if (project.archived) {
        document.querySelector('#archived-banner').hidden = false;
        document.querySelector('#create-form button').disabled = true;
        renameForm.querySelector('input').disabled = true;
        renameForm.querySelector('button').disabled = true;
      }
      document.title = `${project.name} · Workboard`;
      document.querySelector('#task-section').hidden = false;
      renameForm.addEventListener('submit', async event => {
        event.preventDefault();
        const alertBox = document.querySelector('#alert');
        alertBox.textContent = '';
        const name = document.querySelector('#new-project-name').value.trim();
        if (!name) { alertBox.textContent = 'Project name is required'; return; }
        const renameResponse = await fetch(`/api/projects/${encodeURIComponent(id)}`, {
          method: 'PATCH',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ name })
        });
        if (!renameResponse.ok) {
          const error = await renameResponse.json();
          alertBox.textContent = error.error || 'Unable to rename project';
          return;
        }
        project.name = name;
        document.querySelector('#project-name').textContent = name;
        document.title = `${name} · Workboard`;
        document.querySelector('#new-project-name').value = '';
      });
      const taskList = document.querySelector('#tasks');
      const filter = document.querySelector('#task-filter');
      async function loadTasks() {
        const taskResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
        const tasks = await taskResponse.json();
        const visible = tasks.filter(task => filter.value === 'All' || (filter.value === 'Open' ? !task.completed : task.completed));
        taskList.replaceChildren(...visible.map(task => {
          const row = document.createElement('li');
          row.dataset.testid = 'task-row';
          row.className = 'task-row';
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = task.completed;
          checkbox.disabled = project.archived;
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          checkbox.addEventListener('change', async () => {
            await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
            await loadTasks();
          });
          const title = document.createElement('span');
          title.textContent = task.title;
          const renameInput = document.createElement('input');
          renameInput.type = 'text';
          renameInput.setAttribute('aria-label', 'New task title');
          renameInput.value = task.title;
          renameInput.disabled = project.archived;
          const renameButton = document.createElement('button');
          renameButton.type = 'button';
          renameButton.textContent = 'Rename task';
          renameButton.disabled = project.archived;
          renameButton.addEventListener('click', async () => {
            const alertBox = document.querySelector('#alert');
            alertBox.textContent = '';
            const newTitle = renameInput.value.trim();
            if (!newTitle) { alertBox.textContent = 'Task title is required'; return; }
            const renameResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ title: newTitle })
            });
            if (!renameResponse.ok) {
              const error = await renameResponse.json();
              alertBox.textContent = error.error || 'Unable to rename task';
              return;
            }
            await loadTasks();
          });
          const priority = document.createElement('select');
          priority.setAttribute('aria-label', 'Task priority');
          for (const value of ['Low', 'Normal', 'High']) {
            const option = document.createElement('option');
            option.value = value;
            option.textContent = value;
            priority.append(option);
          }
          priority.value = task.priority || 'Normal';
          priority.disabled = project.archived;
          priority.addEventListener('change', async () => {
            const priorityResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ priority: priority.value })
            });
            if (!priorityResponse.ok) {
              const error = await priorityResponse.json();
              document.querySelector('#alert').textContent = error.error || 'Unable to update priority';
              await loadTasks();
            }
          });
          row.append(checkbox, title, renameInput, renameButton, priority);
          return row;
        }));
      }
      filter.addEventListener('change', loadTasks);
      document.querySelector('#create-form').addEventListener('submit', async event => {
        event.preventDefault();
        const alertBox = document.querySelector('#alert');
        alertBox.textContent = '';
        const title = document.querySelector('#task-title').value.trim();
        if (!title) { alertBox.textContent = 'Task title is required'; return; }
        const createResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
        if (!createResponse.ok) { const error = await createResponse.json(); alertBox.textContent = error.error || 'Unable to create task'; return; }
        document.querySelector('#task-title').value = '';
        await loadTasks();
      });
      await loadTasks();
    } else {
      document.querySelector('#missing').hidden = false;
    }
  </script>
</body>
</html>
